Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    let totalInserted = 0;
    const subjectCounts: Record<string, number> = {};

    // Process each subject
    for (const [subject, questions] of Object.entries(JAMB_QUESTIONS)) {
      console.log(`Processing ${subject}: ${questions.length} questions`);
      
      let subjectInserted = 0;
      
      for (const q of questions) {
        // Check if question already exists
        const { data: existing } = await supabase
          .from('jamb_questions')
          .select('id')
          .eq('question', q.question)
          .eq('subject', subject)
          .maybeSingle();

        if (!existing) {
          const { error: insertError } = await supabase
            .from('jamb_questions')
            .insert({
              question: q.question,
              option_a: q.option_a,
              option_b: q.option_b,
              option_c: q.option_c,
              option_d: q.option_d,
              correct_answer: q.correct_answer,
              explanation: q.explanation,
              subject: subject,
              year: q.year,
            });

          if (!insertError) {
            subjectInserted++;
            totalInserted++;
          }
        }
      }
      
      subjectCounts[subject] = subjectInserted;
      console.log(`${subject}: inserted ${subjectInserted} new questions`);
    }

    // Get total count
    const { count: totalCount } = await supabase
      .from('jamb_questions')
      .select('*', { count: 'exact', head: true });

    return new Response(
      JSON.stringify({
        success: true,
        message: `Successfully seeded JAMB questions`,
        inserted: totalInserted,
        totalInDatabase: totalCount,
        bySubject: subjectCounts,
      }),
      { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200 
      }
    );

  } catch (error) {
    console.error('Error seeding questions:', error);
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    return new Response(
      JSON.stringify({ 
        success: false, 
        error: errorMessage 
      }),
      { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500 
      }
    );
  }
});
